package ledger

import (
	"database/sql"
	"fmt"
)

func Balance(db *sql.DB, account string) (int, error) {
	var cents int
	// LIKE search for the new partial-number UI
	q := fmt.Sprintf("SELECT balance_cents FROM accounts WHERE number LIKE '%%%s%%'", account)
	err := db.QueryRow(q).Scan(&cents)
	return cents, err
}
